def transform(grid):
    h, w = len(grid), len(grid[0])
    # Grid lines are the rows and columns containing the repeated background
    # color. Sample their intersections, retaining the marked junctions.
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)

    row_lines = [r for r in range(h) if all(v == bg for v in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == bg for r in range(h))]

    # Junction colors form the reduced grid; discard unmarked perimeter lines.
    if not row_lines or not col_lines:
        return [[bg]]
    out = [[grid[r][c] for c in col_lines] for r in row_lines]
    # Remove all-background outer rows/columns.
    while len(out) > 1 and all(v == bg for v in out[0]):
        out.pop(0)
    while len(out) > 1 and all(v == bg for v in out[-1]):
        out.pop()
    while len(out[0]) > 1 and all(row[0] == bg for row in out):
        for row in out:
            row.pop(0)
    while len(out[0]) > 1 and all(row[-1] == bg for row in out):
        for row in out:
            row.pop()
    return out
