def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify the repeated separator rows and columns by their dominant
    # color, allowing a few differently colored junctions on each line.
    def line_rows(color):
        return [r for r in range(h)
                if sum(v == color for v in grid[r]) >= w - 3]

    def line_cols(color):
        return [c for c in range(w)
                if sum(grid[r][c] == color for r in range(h)) >= h - 3]

    # In this task the separator color is the one filling the interior
    # blocks' borders; find it as the most frequent value.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    rs = line_rows(background)
    cs = line_cols(background)

    # The encoded image is the colors at the crossings of the interior
    # separator lines, with the outer border removed.
    return [[grid[r][c] for c in cs[1:-1]] for r in rs[1:-1]]
